cd "C:/Users/jjdub/AppData/Local/Temp/poly-m3-ws/T8-arm1-run2" && mkdir -p src test && cat > src/host.impl.ts <<'EOF'
import type { CreateHost, Host, NodeView, Outcome } from '../host.ts';

const MAX_TERM = 3;

type Role = 'follower' | 'candidate' | 'leader';

const ok = (): Outcome => ({ ok: true });
const refuse = (reason: string): Outcome => ({ ok: false, reason });

const createHost: CreateHost = async (): Promise<Host> => {
  let role: Role = 'follower';
  let term = 0;
  let shutDown = false;

  return {
    async electionTimeout() {
      if (shutDown) return refuse('the node is shut down');
      if (role === 'leader') return refuse('the leader does not time out');
      if (term >= MAX_TERM) return refuse(`no term after ${MAX_TERM}`);
      role = 'candidate';
      term += 1;
      return ok();
    },
    async electionWon() {
      if (shutDown) return refuse('the node is shut down');
      if (role !== 'candidate') return refuse('only a candidate can win an election');
      role = 'leader';
      return ok();
    },
    async newerTermSeen(t: number) {
      if (shutDown) return refuse('the node is shut down');
      if (typeof t !== 'number' || !Number.isInteger(t) || t < 1 || t > MAX_TERM) {
        return refuse(`the term must be an integer from 1 to ${MAX_TERM}`);
      }
      if (t <= term) return refuse('the term is not newer than the node\'s term');
      role = 'follower';
      term = t;
      return ok();
    },
    async quorumLost() {
      if (shutDown) return refuse('the node is shut down');
      if (role !== 'leader') return refuse('only the leader can lose its quorum');
      role = 'follower';
      return ok();
    },
    async shutdown() {
      if (shutDown) return refuse('the node is already shut down');
      shutDown = true;
      return ok();
    },
    async node(): Promise<NodeView> {
      return { role: shutDown ? 'shutdown' : role, term };
    },
  };
};

export default createHost;
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('lifecycle', async () => {
  const h = await create();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0 });
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1 });
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.electionWon(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'leader', term: 2 });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.quorumLost(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2 });
  assert.equal((await h.newerTermSeen(2)).ok, false);
  assert.equal((await h.newerTermSeen(4)).ok, false);
  assert.equal((await h.newerTermSeen(2.5)).ok, false);
  assert.deepEqual(await h.newerTermSeen(3), { ok: true });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.shutdown(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 3 });
  for (const r of [await h.shutdown(), await h.electionTimeout(), await h.newerTermSeen(3), await h.quorumLost(), await h.electionWon()]) assert.equal(r.ok, false);
});
test('fresh', async () => {
  const a = await create(); await a.electionTimeout();
  assert.deepEqual(await (await create()).node(), { role: 'follower', term: 0 });
});
EOF
npm test 2>&1 | tail -12; npx tsc --noEmit --allowImportingTsExtensions --strict --module nodenext --target esnext src/host.impl.ts test/host.test.ts && echo TSC OK

